// wf.legal.agent > "Prefetch plan" (D-089): the user's question itself is searched before the model runs, with the
// configuration measured in RETRIEVAL_EVAL (T-21). On the PC (T-55) the model skipped the search for 6 of 39
// answerable questions (5 of the 6 in Arabic), and its own rewritten queries found a gold passage for 18 of 33.
const s = $('Start').first().json;
const cfg = $input.first().json.cfg || {};
let r = {};
try { r = typeof cfg['legal.retrieval'] === 'string' ? JSON.parse(cfg['legal.retrieval']) : (cfg['legal.retrieval'] || {}); } catch (e) { r = {}; }
const q = String(s.text || '').replace(/\s+/g, ' ').trim().slice(0, 1000);
return [{ json: { t0: Date.now(), q, url: `${String(cfg['ollama.base_url'] || '').replace(/\/+$/, '')}/api/embed`,
  body: { model: r.model || 'bge-m3', input: [q], truncate: true, keep_alive: cfg['llm.keep_alive'] || '10m' } } }];

// wf.legal.agent > "Prefetch input": embedding answer -> parameters of app.legal_search (lexical without a vector).
const s = $('Start').first().json;
const c = $('Context').first().json.c || {};
const plan = $('Prefetch plan').first().json;
const res = $input.first().json;
let vec = null;
try {
  let b = res.body !== undefined ? res.body : res;
  if (typeof b === 'string') b = JSON.parse(b);
  const v = b && b.embeddings && b.embeddings[0];
  if (Array.isArray(v) && v.length === 1024) vec = `[${v.join(',')}]`;
} catch (e) { vec = null; }
return [{ json: { params: [c.session_id, s.user_id, s.request_id, plan.q, vec, s.jurisdiction || null] } }];

// wf.legal.agent > "Prefetch": the excerpts found for the question, as the text the system message shows the model
// ({{excerpts}} in P5 v2). Numbered like the search tool's, so the model cites them as [n].
const r = $input.first().json.r || {};
const ex = r.excerpts || [];
const text = ex.length
  ? ex.map((e) => `[${e.n}] Source: ${e.source}; type: ${e.type}${e.article ? `; ${e.article}` : ''}\n${String(e.text || '').trim()}`).join('\n\n')
  : '(no excerpt found)';
return [{ json: { found: ex.length, mode: r.mode || null, best_similarity: r.best_similarity ?? null, excerpts_text: text,
  vars: { excerpts: text } } }];

// wf.match.agent and wf.legal.agent > "Agent input"
// Input (Start): {text (masked copy of the message), language, script, jurisdiction, today, user_id, request_id}.
// The system message is the active P6_match_agent (P5_legal_answerer) version from the prompt registry, with its
// variables filled in; the user section (the message between <message> tags) is what the agent receives and what the memory keeps.
const s = $('Start').first().json;
const c = $('Context').first().json.c || {};
const base = { agent: c.agent || 'A3_match_agent', notice_version: c.notice_version || null, session_id: c.session_id,
  user_id: s.user_id, request_id: s.request_id, jurisdiction: s.jurisdiction,
  today: s.today, model: c.model, keep_alive: c.keep_alive, num_ctx: c.num_ctx, max_iterations: c.max_iterations,
  memory_turns: c.memory_turns, memory_messages: c.memory_messages, memory_text: c.memory_text || '',
  answer_max_chars: c.answer_max_chars || 400, t0: Date.now() };
if (!c.prompt) return [{ json: { ...base, ok: false, error_code: 'prompt_missing' } }];
const vars = { message: s.text, jurisdiction: s.jurisdiction || 'unknown', today: s.today, language: s.language || 'fr',
  script: s.script || 'latin' };
// variables computed just before this node (the Legal agent's excerpts, D-089); other agents: the Context row, no vars
Object.assign(vars, ($input.first().json || {}).vars || {});
const fill = (t) => t.replace(/\{\{\s*([a-z_]+)\s*\}\}/gi, (m, k) => (k in vars ? String(vars[k]) : m));
const m = /##\s*system\s*\n([\s\S]*?)\n##\s*user\s*\n([\s\S]*)$/i.exec(c.prompt.template);
if (!m) return [{ json: { ...base, ok: false, error_code: 'prompt_invalid' } }];
const params = c.prompt.params || {};
return [{ json: { ...base, ok: true, system: fill(m[1].trim()), text: fill(m[2].trim()),
  prompt_version_id: c.prompt.version_id, prompt_version: c.prompt.version, num_predict: params.num_predict || 400 } }];

// wf.legal.agent > "Check answer"
// The AI Agent node's answer -> a checked answer with its citations, or an abstention (spec 10.6), and one trace step.
//  - [NOT_FOUND] from the model, no search made (the question is searched before the model, D-089), or no valid
//    [n] marker left -> abstained (abstain_reason says which)
//  - markers whose number search_law did not give are removed (warning legal_invalid_citation); the kept ones are
//    renumbered 1, 2, ... and the citations list follows that order
//  - every number in the answer must come from the message, the memory or an excerpt (agent_check.checkAnswer);
//    otherwise -> abstained, reason unsupported_numbers (a wrong delay or amount is worse than no answer)
//  - no answer at all (model down, too many iterations) -> ok false, and the orchestrator answers 503
// A3 Match agent checks (D-084), shared by the agent workflow and the unit tests.
//  - toolCalls(steps): the AI Agent node's intermediate steps as [{tool, input, output}] (output parsed when JSON).
//  - numbersIn(text): every reading of every number written in a text (see readings).
//  - checkAnswer(answer, sources): every number of two digits or more in the answer must appear in one of the
//    sources (the user's message, the tool results). Small numbers (result positions, counts up to 10) pass.
//  - fallbackMask(text): e-mails and long digit runs masked, used only when the Text service did not answer.
//  - plainText(answer): Markdown removed (bold, italics, headings, list markers, links), lines joined (D-085).
//  - shorten(text, max): cut at the last sentence end that fits, else at a word, with an ellipsis (D-085).

function toolCalls(steps) {
  return (Array.isArray(steps) ? steps : []).map((s) => {
    const a = s.action || {};
    let out = s.observation;
    if (typeof out === 'string') { try { out = JSON.parse(out); } catch (e) { /* keep the text */ } }
    if (Array.isArray(out) && out.length === 1) out = out[0];          // a workflow tool answers with its items
    let input = a.toolInput;
    if (typeof input === 'string') { try { input = JSON.parse(input); } catch (e) { /* keep the text */ } }
    return { tool: a.tool || null, input: input ?? null, output: out ?? null };
  });
}

// Each number written in a text, with its possible readings: "450.000" is 450 (Tunisian dinars, three decimals) or
// 450000 (dot as thousands separator); "1.225.000" is 1225000; "450,5" is 450.5.
function readings(text) {
  const out = [];
  for (const m of String(text || '').matchAll(/\d{1,3}(?:\.\d{3})+(?!\d|,\d)|\d+(?:[.,]\d+)?/g)) {
    const raw = m[0];
    const alts = new Set();
    if (/^\d{1,3}(?:\.\d{3})+$/.test(raw)) alts.add(Number(raw.replace(/\./g, '')));
    const v = Number(raw.replace(',', '.'));
    if (Number.isFinite(v)) alts.add(v);
    out.push([...alts]);
  }
  return out;
}

function numbersIn(text) {
  return readings(text).flat();
}

function checkAnswer(answer, sources) {
  const allowed = new Set();
  for (const src of sources || []) {
    const text = typeof src === 'string' ? src : JSON.stringify(src ?? '');
    for (const n of numbersIn(text)) {
      allowed.add(n);
      allowed.add(Math.round(n));
    }
  }
  const unsupported = [];
  for (const alts of readings(answer)) {
    if (alts.some((n) => Number.isInteger(n) && n <= 10)) continue;
    if (alts.some((n) => allowed.has(n) || allowed.has(Math.round(n)))) continue;
    unsupported.push(alts[alts.length - 1]);
  }
  return { ok: unsupported.length === 0, unsupported };
}

function fallbackMask(text) {
  return String(text || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '<EMAIL>')
    .replace(/\+?\d[\d .-]{6,}\d/g, (m) => (m.replace(/\D/g, '').length >= 8 ? '<PHONE>' : m));
}

function plainText(answer) {
  const lines = String(answer || '').replace(/\r/g, '').split('\n').map((l) => l
    .replace(/^\s{0,3}#{1,6}\s+/, '')                      // headings
    .replace(/^\s*(?:[-*+\u2022]|\d+[.)])\s+/, '')            // list markers ("1." too: positions are said in words)
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')                // links: keep the text
    .replace(/(\*\*|__)(.+?)\1/g, '$2')                       // bold
    .replace(/(^|[^\w*])[*_]([^*_\n]+)[*_](?=[^\w*]|$)/g, '$1$2') // italics
    .replace(/`([^`]*)`/g, '$1')
    .replace(/[*_]{2,}/g, '')
    .trim()).filter(Boolean);
  return lines.join(' ').replace(/\s{2,}/g, ' ').trim();
}

function shorten(text, max) {
  const t = String(text || '');
  if (!max || Array.from(t).length <= max) return { text: t, cut: false };
  const head = Array.from(t).slice(0, max).join('');
  const ends = [...head.matchAll(/[.!?\u061F\u06D4](?=\s|$)/g)].map((m) => m.index + 1);
  if (ends.length && ends[ends.length - 1] >= max * 0.4) return { text: head.slice(0, ends[ends.length - 1]).trim(), cut: true };
  const sp = head.lastIndexOf(' ');
  return { text: (sp > max * 0.4 ? head.slice(0, sp) : head).trim() + '\u2026', cut: true };
}

if (typeof module !== 'undefined') module.exports = { toolCalls, readings, numbersIn, checkAnswer, fallbackMask, plainText, shorten };

// A5 Legal agent checks (D-087), shared by the agent workflow and the unit tests.
//  - parseLegal(text): reads the tokens [NOT_FOUND] and [CONFLICT] and removes them; moves a marker written after a
//    sentence end into that sentence ("dues. [1]" -> "dues [1].").
//  - markers(text): the citation numbers written in the text, in order: "[2]", "[1, 3]", "[1][2]".
//  - renumber(text, valid): keeps the markers whose number is in `valid` (numbers the search tool gave), drops the
//    others, and renumbers the kept ones 1, 2, ... in order of first appearance. Returns {text, used (the original
//    numbers, in the new order), invalid (numbers dropped)}.
//  - stripMarkers(text): the text without markers, for the number check (a marker is not a claim).
//  - uncited(text): sentences that state something without a marker (sentences of fewer than four words are skipped).

const MARK_RE = /\[\s*(\d{1,3}(?:\s*[,;]\s*\d{1,3})*)\s*\]/g;

function parseLegal(text) {
  let t = String(text || '').trim();
  let notFound = false;
  let conflict = false;
  for (;;) {
    const m = /^\[?\s*(NOT_FOUND|CONFLICT)\s*\]?\s*[:.-]?\s*/i.exec(t);
    if (!m) break;
    if (m[1].toUpperCase() === 'NOT_FOUND') notFound = true; else conflict = true;
    t = t.slice(m[0].length);
  }
  // a model may also put the token elsewhere: it still counts, and is removed
  if (/\[\s*NOT_FOUND\s*\]/i.test(t)) { notFound = true; t = t.replace(/\[\s*NOT_FOUND\s*\]/gi, ' '); }
  if (/\[\s*CONFLICT\s*\]/i.test(t)) { conflict = true; t = t.replace(/\[\s*CONFLICT\s*\]/gi, ' '); }
  // "... dues. [1] Voir" -> "... dues [1]. Voir": a marker belongs to the sentence before it
  t = t.replace(/([.!?\u061F])\s*((?:\[\s*\d{1,3}(?:\s*[,;]\s*\d{1,3})*\s*\]\s*)+)/g, (m, p, marks) => ` ${marks.trim()}${p} `);
  return { notFound, conflict, text: t.replace(/\s+([.!?\u061F])/g, '$1').replace(/\s{2,}/g, ' ').trim() };
}

function markers(text) {
  const out = [];
  for (const m of String(text || '').matchAll(MARK_RE)) for (const x of m[1].split(/[,;]/)) out.push(Number(x.trim()));
  return out;
}

function renumber(text, valid) {
  const ok = new Set((valid || []).map(Number));
  const order = [];
  const invalid = [];
  const out = String(text || '').replace(MARK_RE, (all, list) => {
    const nums = list.split(/[,;]/).map((x) => Number(x.trim()));
    const kept = [];
    for (const n of nums) {
      if (!ok.has(n)) { invalid.push(n); continue; }
      if (!order.includes(n)) order.push(n);
      const k = order.indexOf(n) + 1;
      if (!kept.includes(k)) kept.push(k);
    }
    return kept.length ? '[' + kept.join(', ') + ']' : '';
  }).replace(/\s+([.,;:!?؟])/g, '$1').replace(/\s{2,}/g, ' ').trim();
  return { text: out, used: order, invalid };
}

function stripMarkers(text) {
  return String(text || '').replace(MARK_RE, ' ').replace(/\s{2,}/g, ' ').trim();
}

function uncited(text) {
  const sentences = String(text || '').split(/(?<=[.!?؟])\s+/).map((s) => s.trim()).filter(Boolean);
  return sentences.filter((s) => s.split(/\s+/).length >= 4 && !markers(s).length).length;
}

if (typeof module !== 'undefined') module.exports = { parseLegal, markers, renumber, stripMarkers, uncited };

const a = $('Agent input').first().json;
const r = $('Legal agent').first().json;
const src = ($input.first().json || {}).s || { sources: [], searches: 0, best_similarity: null };
const calls = toolCalls(r.intermediateSteps);
const latency = Date.now() - a.t0;
const err = r.error ? String(r.error.message || r.error).slice(0, 300) : null;
const raw = typeof r.output === 'string' ? r.output.trim() : '';
const markdown = /\*\*|__|^\s*(?:[-*+•]|#{1,6})\s|\[[^\]]+\]\(/m.test(raw);
const searches = calls.filter((x) => x.tool === 'search_law');
const sources = Array.isArray(src.sources) ? src.sources : [];
const byN = new Map(sources.map((x) => [Number(x.n), x]));
const p = parseLegal(plainText(raw));
const warnings = [];
let status = 'answered';
let reason = null;
let answer = null;
let missing = null;
let used = [];
let invalid = [];
let cut = false;
let unc = 0;
let pre = null;
try { pre = $('Prefetch').first().json; } catch (e) { pre = null; }
const sourcesText = [a.text, a.memory_text, pre ? pre.excerpts_text : '', ...calls.map((x) => x.output)];
if (!err && raw) {
  if (p.notFound) {
    status = 'abstained'; reason = 'not_found';
    const t = stripMarkers(p.text);
    if (t && checkAnswer(t, sourcesText).ok) missing = shorten(t, 300).text;
  } else if (!searches.length && !(Number(src.searches) > 0)) {
    status = 'abstained'; reason = 'no_search';
  } else {
    const rn = renumber(p.text, [...byN.keys()]);
    invalid = rn.invalid;
    if (invalid.length) warnings.push('legal_invalid_citation');
    if (!rn.used.length) { status = 'abstained'; reason = 'no_citation'; }
    else {
      const chk = checkAnswer(stripMarkers(rn.text), sourcesText);
      if (!chk.ok) { status = 'abstained'; reason = 'unsupported_numbers'; }
      else {
        const sh = shorten(rn.text, a.answer_max_chars || 900);
        answer = sh.text; cut = sh.cut;
        if (cut) warnings.push('legal_answer_cut');
        // citations still in the text after the cut (numbered by first appearance, so a cut keeps 1..j)
        const left = new Set(markers(answer));
        used = rn.used.filter((n, i) => left.has(i + 1));
        if (!used.length) { status = 'abstained'; reason = 'no_citation'; answer = null; }
        else {
          unc = uncited(answer);
          if (unc) warnings.push('legal_uncited_sentences');
        }
      }
    }
  }
}
const ok = !err && !!raw;
const citations = used.map((n, i) => {
  const x = byN.get(n) || {};
  return { n: i + 1, title: x.title || null, cite_as: x.cite_as || null, url: x.url || null, source_type: x.source_type || null,
    reliability: x.reliability ?? null, article: x.article || null, retrieved_at: x.retrieved_at || null, chunk_id: x.chunk_id || null };
});
const conflict = status === 'answered' && p.conflict;
// no raw text in the trace (D-062): sizes, counts and chunk ids only
const step = { agent: 'A5_legal_agent', prompt_version_id: a.prompt_version_id || null, model: a.model || null,
  input: { chars: Array.from(a.text || '').length, memory_messages: a.memory_messages ?? null },
  output: { status, abstain_reason: reason, conflict, conflict_token: p.conflict, answer_chars: answer ? Array.from(answer).length : 0,
            raw_chars: Array.from(raw).length, markdown_removed: markdown, cut, citations: citations.length,
            invalid_citations: invalid.length, uncited_sentences: unc, searches: searches.length,
            prefetched: pre ? pre.found : null, searches_total: Number(src.searches) || 0,
            best_similarity: src.best_similarity ?? null,
            retrieved: sources.filter((x) => x.request_id === a.request_id)
              .map((x) => ({ n: x.n, chunk_id: x.chunk_id, similarity: x.similarity ?? null })) },
  tool_calls: calls.map((x) => ({ tool: x.tool,
    input_chars: x.input && x.input.query ? Array.from(String(x.input.query)).length : undefined,
    found: x.output && typeof x.output === 'object' ? (x.output.found ?? null) : null })),
  latency_ms: latency, tokens_in: null, tokens_out: null,
  error: err || (ok ? null : 'no_answer') };
if (!ok) return [{ json: { ok: false, error_code: err ? 'agent_failed' : 'no_answer', steps: [step] } }];
return [{ json: { ok: true, status, answer, abstained: status === 'abstained', abstain_reason: reason, conflict, citations,
  missing_information: missing, notice_version: a.notice_version, warnings, steps: [step],
  agent: { tool_calls: calls.map((x) => x.tool), memory_messages: a.memory_messages } } }];

// wf.match.agent and wf.legal.agent > "No prompt": the registry has no active version of the agent's prompt.
const a = $input.first().json;
return [{ json: { ok: false, error_code: a.error_code, steps: [{ agent: a.agent || 'A3_match_agent', model: null, input: {}, output: null,
  latency_ms: 0, tokens_in: 0, tokens_out: 0, error: a.error_code }] } }];
